function armsHeroPresent(panel, id) {
  const box = panel.querySelector('[data-arms-inspector]');
  const detail = panel.querySelector('details[data-arms-help][open]');
  const key = id || (detail && detail.dataset.armsHelp);
  const node = B.armsIntegrated.TREE.find(n => n.id === key);
  const note = panel.querySelector('[data-arms-status]');
  box.hidden = !node && !note.textContent;
  panel.querySelector('[data-arms-heading]').textContent = node ? node.ru : 'Очки талантов';
  panel.querySelector('[data-arms-effect]').textContent = node ? armsHeroEffect(node.id) : '';
}
function armsHeroRefusal(button, result) {
  const P = B.armsIntegrated, level = hLevel('me'), alloc = armsHeroData(S.hero, level);
  const node = P.TREE.find(n => n.id === button.dataset.armsNode);
  const removing = button.dataset.armsDelta === '-1' || result.removing;
  if (!node) return 'Сейчас это изменение недоступно.';
  const rank = alloc[node.id] || 0;
  if (P.CONFIG.unavailable.includes(node.id)) return 'Этот талант пока недоступен для изучения.';
  if (removing && !rank) return 'Нечего снимать: в этот талант ещё не вложены очки.';
  if (!removing && rank >= node.max) return 'Уже максимальный ранг.';
  if (!removing && P.validate(alloc, level).spent >= P.points(level)) return 'Все очки распределены. Снимите другой ранг, чтобы изменить выбор.';
  if (removing) return 'Этот ранг нужен талантам следующих рядов. Сначала снимите зависимые ранги.';
  const row = (result.errors || []).map(x => x.match(/Ряд (\d+) требует (\d+)/)).find(Boolean);
  if (row) return 'Ряд ' + row[1] + ': сначала вложите не менее ' + row[2] + ' очков в предыдущие ряды.';
  return 'Сначала полностью изучите требуемый талант.';
}
document.addEventListener('toggle', function (ev) {
  const detail = ev.target;
  if (!detail.isConnected || !detail.matches || !detail.matches('details[data-arms-help]')) return;
  const panel = detail.closest('[data-arms-panel]');
  if (detail.open) panel.querySelectorAll('details[data-arms-help][open]').forEach(x => { if (x !== detail) x.open = false; });
  armsHeroPresent(panel);
}, true);
document.addEventListener('click', function (ev) {
  const button = ev.target.closest('[data-arms-inspector-close]');
  if (!button) return;
  ev.preventDefault();
  const panel = button.closest('[data-arms-panel]');
  const summary = panel.querySelector('details[open] summary');
  panel.querySelectorAll('details[open]').forEach(x => { x.open = false; });
  panel.querySelector('[data-arms-status]').textContent = '';
  armsHeroPresent(panel);
  summary?.focus({preventScroll:true});
}, true);
function armsHeroAction(ev) {

if (note) {
  note.textContent = armsHeroRefusal(button, Object.assign({}, result, {removing: ev.type === 'contextmenu'}));
  armsHeroPresent(panel, button.dataset.armsNode);
}
